class BIT:
    def __init__(self, n={{n}}):
        self.n = n
        self.t = [0]*(n+1)
    def update(self, i, v):
        i += 1
        while i <= self.n:
            self.t[i] += v
            i += i & -i
    def query(self, i):
        i += 1; s = 0
        while i > 0:
            s += self.t[i]
            i -= i & -i
        return s
    def range_sum(self, l, r):
        return self.query(r) - (self.query(l-1) if l else 0)
